CREATE TABLE buku (id INTEGER PRIMARY KEY, nama TEXT NOT NULL, jenis TEXT NOT NULL);
CREATE TABLE jurnal (id INTEGER PRIMARY KEY, jenis TEXT NOT NULL);
CREATE TABLE posting (jurnal_id INTEGER NOT NULL REFERENCES jurnal (id), buku_id INTEGER NOT NULL REFERENCES buku (id), jumlah INTEGER NOT NULL CHECK (jumlah <> 0));
-- file_bank memerankan file CSV untuk bank; di lab, file itu ditulis ke disk, di luar database
