CREATE TEMP TABLE cair AS
  SELECT (SELECT MAX(id) FROM jurnal) + ROW_NUMBER() OVER (ORDER BY b.id) AS jurnal_id,
         b.id AS buku_id, b.nama, SUM(p.jumlah) AS jumlah
  FROM buku b JOIN posting p ON p.buku_id = b.id
  WHERE b.jenis = 'warung' GROUP BY b.id HAVING SUM(p.jumlah) > 0;
INSERT INTO jurnal SELECT jurnal_id, 'pencairan' FROM cair;
INSERT INTO posting SELECT jurnal_id, buku_id, -jumlah FROM cair;
INSERT INTO posting SELECT jurnal_id, 1, jumlah FROM cair;
INSERT INTO file_bank (akun_warung, nama_penerima, jumlah) SELECT buku_id, nama, jumlah FROM cair;
SELECT COUNT(*) || ' warung dicairkan, Rp' || replace(printf('%,d', COALESCE(SUM(jumlah), 0)), ',', '.') FROM cair;
DROP TABLE cair;

